/// What the Round screen shows for every Exercise Laboratory example,
/// recorded by `exercise_laboratory_254_test.dart` in record mode
/// (`QQL_RECORD_PRESENTATION`). First recorded on 27 September 2026 before
/// the Build 256 Session 3 refactor of the learner runtime onto canonical
/// data; re-recorded on 27 September 2026 for Build 256 Revision 4 (the
/// preset catalogue), whose regenerated Laboratory has 107 examples. Every
/// record of an example that existed before is equal to its Session 3 record
/// except where `docs/256_VALIDATION.md` lists a deliberate change (the
/// inline-gap examples of Build the translation are Drag the blocks into the
/// gaps with a clue, no longer translations). Later work must keep every
/// record equal except where a documented deliberate change says otherwise.
/// Build 258 Revision 3 added the two Page examples; no existing record changed.
/// Build 258 Revision 4 re-recorded those two: Share and Print sit under a Page.
/// Build 259 Revision 0 re-recorded 37 records (`docs/259_VALIDATION.md`): an
/// authored instruction takes the place of the standard line, the Choose
/// examples ask in their question, the picture and Assign examples show their
/// instruction, Recognize characters text to image asks in its question, and
/// Match by meaning's instructions are in English.
/// Build 259 Revision 5 re-recorded the ten Dialogue lines: a line shows no
/// instruction. Revision 7 re-recorded 41 records: the standard lines no
/// longer repeat their title, and Type / Build the translation name the
/// language of the answer instead of a fixed "Translate from … into …" line.
/// Revision 8 re-recorded 3 records: the Firenze gap, the farm-animal hint
/// and the second block of "Il gatto ___.".
/// Build 261 Revision 3 re-recorded 70 records: the title is the name of the
/// preset that represents the exercise (WORD ORDER, TRUE OR FALSE, READ AND
/// ANSWER, …), and Pick the translation has one (PICK THE TRANSLATION); no
/// instruction changed. Each example is played outside a Story here, so the
/// Story lesson's examples show titles that a Story does not.
/// Build 261 Revision 5 re-recorded 3 records: the Read and answer
/// dialogues' answers no longer copy their text.
/// Build 263 Revision 0 re-recorded 19 records: no standard line opens
/// with the first word of its title (Pick the translation chooses, the
/// spelling presets form, the typed ones write).
/// Build 263 Revision 2 follow-up re-recorded 2 records: picture answers
/// are large squares by default, so each button holds its picture.
/// Build 268 Revision 0 re-recorded the 8 Flashcards and Picture
/// flashcards: a card has two sides, so before turning only the word shows,
/// with Turn over beside Got it, and the instruction asks for the meaning;
/// the meaning, the picture and the example are on the back. The two Note
/// cards are unchanged.
